// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // The deployer (this test contract) is the current owner.
        // Rule: the current owner can ALWAYS transfer ownership to any address.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == newOwner);
    }
}
